<script setup lang="ts">
import { computed, nextTick, ref, watch } from "vue";
import { useMediaQuery } from "@vueuse/core";
import { ArrowDownLeft, ArrowUpRight, Ban, ChevronDown, Search, SlidersHorizontal, X } from "lucide-vue-next";
import type { KasCategory, KasTransaction, TransactionAuditTimeline } from "@/services/admin/kasService";
import type { KasFilterTipe } from "@/composables/admin/kas/useKasState";
import { canVoid } from "@/utils/permissions";
import { useAuthStore } from "@/stores/authStore";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import StatusIndicator from "@/components/ui/status/StatusIndicator.vue";
import Timeline from "@/components/ui/timeline/Timeline.vue";
import { EmptyState, ErrorState } from "@/components/ui/data-state";
import { DropdownMenu, DropdownMenuContent, DropdownMenuRadioGroup, DropdownMenuRadioItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { getCurrentWibPeriod } from "../../../../shared/contracts/index.ts";

const props = defineProps<{ transactions: KasTransaction[]; categories: KasCategory[]; month: number; year: number; years: number[]; flow: KasFilterTipe; category: number | "semua"; saldoAwal: number; totalMasuk: number; totalKeluar: number; saldoAkhir: number; pendingIds: Set<number>; loading: boolean; loadError: string; hasLoaded: boolean; timeline: TransactionAuditTimeline | null; timelineTransactionId: number | null; timelineLoading: boolean; timelineError: string; formatRupiah: (value: number) => string; formatWaktuAudit: (value?: string | null) => string }>();
const emit = defineEmits<{ reload: []; "update:month": [number]; "update:year": [number]; "update:flow": [KasFilterTipe]; "update:category": [number | "semua"]; select: [number]; retryTimeline: [number]; void: [number] }>();
const authStore = useAuthStore();
const query = ref(""); const filtersExpanded = ref(false); const detailOpen = ref(false); const activeId = ref<number | null>(null); const status = ref<"semua" | "approved" | "void">("semua");
const isWideDesktop = useMediaQuery("(min-width: 1280px)");
const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
const periodLabel = computed(() => `${months[props.month - 1]} ${props.year}`);
const results = computed(() => props.transactions.filter((item) => { const needle=query.value.trim().toLocaleLowerCase("id-ID"); return ["approved","void"].includes(item.status) && (status.value==="semua" || item.status===status.value) && (!needle || [item.keperluan,item.keterangan,item.kategori,item.seksi].filter(Boolean).join(" ").toLocaleLowerCase("id-ID").includes(needle)); }));
const activeTransaction = computed(() => results.value.find((item) => item.id === activeId.value) ?? results.value[0] ?? null);
const visibleTimeline = computed(() => props.timelineTransactionId === activeTransaction.value?.id ? props.timeline : null);
const labels: Record<string,string>={created:"Transaksi dibuat",submitted:"Proposal diajukan",approved_ketua:"Disetujui Ketua",approved_bendahara:"Dicairkan Bendahara",rejected:"Proposal ditolak",voided:"Transaksi dibatalkan"};
const timelineItems = computed(() => (visibleTimeline.value?.events ?? []).map((event) => ({ id:event.id,title:labels[event.event_type]??event.event_type,description:`${props.formatWaktuAudit(event.created_at)} · ${event.actor_name || `Pengguna #${event.actor_id}`}${event.reason ? ` · ${event.reason}` : ""}` })));
const currentPeriod=getCurrentWibPeriod(); const currentMonth=currentPeriod.month; const currentYear=currentPeriod.year;
const choose=(id:number)=>{activeId.value=id;detailOpen.value=window.innerWidth < 1280};
const requestVoid=async(id:number)=>{detailOpen.value=false;await nextTick();emit("void",id)};
const reset=()=>{query.value="";status.value="semua";emit("update:flow","semua");emit("update:category","semua");emit("update:month",currentMonth);emit("update:year",currentYear);filtersExpanded.value=false};
watch(activeTransaction,(value,old)=>{if(value&&value.id!==old?.id){activeId.value=value.id;emit("select",value.id)}},{immediate:true});
watch(isWideDesktop,(wide)=>{if(wide)detailOpen.value=false});
</script>

<template>
  <div>
    <div v-if="loading && !hasLoaded" role="status" class="grid min-h-72 place-items-center rounded-xl border bg-card text-sm text-muted-foreground">Memuat ruang kerja transaksi…</div>
    <ErrorState v-else-if="loadError && !hasLoaded" title="Transaksi belum dapat dimuat" :description="loadError" @retry="emit('reload')" />
    <template v-else>
      <Card class="mb-3 gap-0 py-0 md:mb-4">
        <CardContent class="grid gap-4 py-4 md:grid-cols-[minmax(14rem,.8fr)_1fr] md:items-center md:py-3">
          <div><p class="text-xs font-medium text-muted-foreground">Posisi kas · {{ periodLabel }}</p><p class="mt-1 text-3xl font-semibold tracking-tight tabular-nums">{{ formatRupiah(saldoAkhir) }}</p><p class="mt-1 text-xs text-muted-foreground">Saldo awal {{ formatRupiah(saldoAwal) }}</p></div>
          <div class="grid grid-cols-2 gap-2"><div class="rounded-lg bg-success-soft p-3 md:py-2"><p class="text-xs text-success">Dana masuk</p><strong class="mt-1 block tabular-nums text-success">+ {{ formatRupiah(totalMasuk) }}</strong></div><div class="rounded-lg bg-destructive/8 p-3 md:py-2"><p class="text-xs text-destructive">Dana keluar</p><strong class="mt-1 block tabular-nums text-destructive">− {{ formatRupiah(totalKeluar) }}</strong></div></div>
        </CardContent>
      </Card>

      <div class="grid gap-3 xl:h-[36rem] xl:grid-cols-[minmax(20rem,.9fr)_minmax(28rem,1.1fr)]">
        <Card class="min-h-[28rem] gap-0 py-0 xl:min-h-0">
          <CardHeader class="border-b py-3"><div class="flex items-center justify-between gap-3"><div><p class="font-semibold">Aktivitas kas</p><p class="text-xs text-muted-foreground">{{ results.length }} transaksi · {{ periodLabel }}</p></div></div><Collapsible v-model:open="filtersExpanded" class="mt-2"><div class="grid grid-cols-[minmax(0,1fr)_auto] gap-2"><label class="relative"><span class="sr-only">Cari transaksi</span><Search class="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input v-model="query" class="h-11 pl-9 xl:h-8" placeholder="Cari transaksi"/></label><CollapsibleTrigger as-child><Button variant="outline" class="h-11 gap-2 px-3 xl:h-8" aria-label="Filter transaksi"><SlidersHorizontal/><span class="hidden sm:inline">Filter cepat</span><ChevronDown class="transition-transform" :class="filtersExpanded&&'rotate-180'"/></Button></CollapsibleTrigger></div><CollapsibleContent><div data-filter-surface class="mt-2 rounded-md bg-muted/45 p-2.5"><div data-filter-segments class="mt-2 grid gap-2"><div><p class="mb-1 text-xs text-muted-foreground">Arus kas</p><div class="grid grid-cols-3 rounded-md border bg-card p-1"><Button v-for="item in [{value:'semua',label:'Semua'},{value:'pemasukan',label:'Masuk'},{value:'pengeluaran',label:'Keluar'}]" :key="item.value" size="sm" class="h-11 min-w-0 px-1 xl:h-7" :variant="flow===item.value?'secondary':'ghost'" :aria-pressed="flow===item.value" @click="emit('update:flow',item.value as KasFilterTipe)">{{ item.label }}</Button></div></div><div><p class="mb-1 text-xs text-muted-foreground">Status transaksi</p><div class="grid grid-cols-3 rounded-md border bg-card p-1"><Button v-for="item in [{value:'semua',label:'Semua'},{value:'approved',label:'Disetujui'},{value:'void',label:'Dibatalkan'}]" :key="item.value" size="sm" class="h-11 min-w-0 px-1 xl:h-7" :variant="status===item.value?'secondary':'ghost'" :aria-pressed="status===item.value" @click="status=item.value as typeof status">{{ item.label }}</Button></div></div></div><div data-filter-primary class="mt-2 grid grid-cols-[minmax(0,1fr)_auto] items-end gap-2 md:grid-cols-[auto_minmax(0,1fr)_auto]"><div class="col-span-2 md:col-span-1"><p class="mb-1 text-xs text-muted-foreground">Periode</p><div class="grid w-full grid-cols-[2fr_1fr] gap-1 md:w-56"><DropdownMenu><DropdownMenuTrigger as-child><Button variant="outline" class="h-11 min-w-0 justify-between px-3 xl:h-8">{{ months[month-1] }}<ChevronDown/></Button></DropdownMenuTrigger><DropdownMenuContent align="start" class="w-72 !rounded-md"><DropdownMenuRadioGroup class="grid grid-cols-2" :model-value="String(month)" @update:model-value="emit('update:month',Number($event))"><DropdownMenuRadioItem v-for="(name,index) in months" :key="name" :value="String(index+1)" class="h-11 rounded-sm py-0 xl:h-8">{{ name }}</DropdownMenuRadioItem></DropdownMenuRadioGroup></DropdownMenuContent></DropdownMenu><DropdownMenu><DropdownMenuTrigger as-child><Button variant="outline" class="h-11 min-w-0 justify-between gap-1 px-2 xl:h-8">{{ year }}<ChevronDown/></Button></DropdownMenuTrigger><DropdownMenuContent align="start" class="w-28 rounded-md"><DropdownMenuRadioGroup :model-value="String(year)" @update:model-value="emit('update:year',Number($event))"><DropdownMenuRadioItem v-for="item in years" :key="item" :value="String(item)" class="h-11 rounded-sm py-0 xl:h-8">{{ item }}</DropdownMenuRadioItem></DropdownMenuRadioGroup></DropdownMenuContent></DropdownMenu></div></div><div class="min-w-0"><p class="mb-1 text-xs text-muted-foreground">Kategori</p><DropdownMenu><DropdownMenuTrigger as-child><Button variant="outline" class="h-11 w-full min-w-0 justify-between gap-2 px-3 xl:h-8"><span class="truncate">{{ category==='semua'?'Semua':categories.find(item=>item.id===category)?.nama_kategori||'Kategori' }}</span><ChevronDown/></Button></DropdownMenuTrigger><DropdownMenuContent align="start" class="w-52 rounded-md"><DropdownMenuRadioGroup :model-value="String(category)" @update:model-value="emit('update:category',$event==='semua'?'semua':Number($event))"><DropdownMenuRadioItem value="semua" class="h-11 rounded-sm py-0 xl:h-8">Semua kategori</DropdownMenuRadioItem><DropdownMenuRadioItem v-for="item in categories" :key="item.id" :value="String(item.id)" class="h-11 rounded-sm py-0 xl:h-8">{{ item.nama_kategori }}</DropdownMenuRadioItem></DropdownMenuRadioGroup></DropdownMenuContent></DropdownMenu></div><Button variant="ghost" size="sm" class="ml-auto h-11 border-l px-2 xl:h-8" @click="reset"><X/> Reset</Button></div></div></CollapsibleContent></Collapsible></CardHeader>
          <ScrollArea class="min-h-0 flex-1"><div v-if="results.length" class="grid gap-2 p-2"><Button v-for="item in results" :key="item.id" variant="ghost" class="h-auto min-h-[5.25rem] w-full max-w-full overflow-hidden justify-start whitespace-normal rounded-lg p-3 text-left md:min-h-[4.5rem]" :class="activeTransaction?.id===item.id&&'bg-accent ring-1 ring-primary/25'" :aria-label="`Pilih transaksi ${item.keperluan}`" :aria-pressed="activeTransaction?.id===item.id" :data-transaction-row="item.id" @click="choose(item.id)"><span class="grid size-9 shrink-0 place-items-center rounded-md md:size-8" :class="item.tipe==='pemasukan'?'bg-success-soft text-success':'bg-destructive/10 text-destructive'"><ArrowUpRight v-if="item.tipe==='pemasukan'"/><ArrowDownLeft v-else/></span><span class="min-w-0 flex-1"><span class="block truncate font-semibold">{{ item.keperluan }}</span><span class="mt-1 block truncate text-xs font-normal text-muted-foreground">{{ item.tanggal }} · {{ item.kategori }}</span></span><span class="text-right"><strong class="block tabular-nums" :class="item.tipe==='pemasukan'?'text-success':'text-destructive'">{{ item.tipe==='pemasukan'?'+':'−' }} {{ formatRupiah(item.jumlah) }}</strong><span class="mt-1 block text-xs font-normal text-muted-foreground">{{ item.status==='void'?'Dibatalkan':'Disetujui' }}</span></span></Button></div><EmptyState v-else title="Tidak ada transaksi" description="Ubah pencarian atau filter."/></ScrollArea>
        </Card>

        <Card v-if="activeTransaction" class="hidden min-h-0 gap-0 py-0 xl:flex">
          <CardHeader class="border-b py-3"><div class="flex items-start justify-between gap-3"><div><p class="text-xs text-muted-foreground">DOSSIER #{{ activeTransaction.id }}</p><p class="mt-1 text-lg font-semibold">{{ activeTransaction.keperluan }}</p><p class="text-xs text-muted-foreground">{{ activeTransaction.tanggal }} · {{ activeTransaction.kategori }}</p></div><StatusIndicator :tone="activeTransaction.status==='void'?'destructive':'success'">{{ activeTransaction.status==='void'?'Dibatalkan':'Disetujui' }}</StatusIndicator></div></CardHeader>
          <ScrollArea class="min-h-0 flex-1"><CardContent class="space-y-5 py-4"><section v-if="activeTransaction.keterangan"><h3 class="font-semibold">Keterangan</h3><p class="mt-1 text-sm leading-6 text-muted-foreground">{{ activeTransaction.keterangan }}</p></section><p class="text-3xl font-semibold tabular-nums" :class="activeTransaction.tipe==='pemasukan'?'text-success':'text-destructive'">{{ activeTransaction.tipe==='pemasukan'?'+':'−' }} {{ formatRupiah(activeTransaction.jumlah) }}</p><div v-if="activeTransaction.status==='void'" class="rounded-lg bg-destructive/5 p-3 text-sm"><strong>Alasan pembatalan</strong><p class="mt-1">{{ activeTransaction.void_reason||'Alasan tidak tersedia pada data legacy.' }}</p></div><section><h3 class="font-semibold">Jejak keputusan</h3><p class="mb-4 text-xs text-muted-foreground">Audit transaksi aktif</p><p v-if="timelineLoading||timelineTransactionId!==activeTransaction.id" role="status" class="text-sm text-muted-foreground">Memuat riwayat…</p><p v-else-if="timelineError" role="alert" class="text-sm text-destructive">{{ timelineError }} <Button variant="link" class="h-8 px-1" @click="emit('retryTimeline',activeTransaction.id)">Coba lagi</Button></p><p v-else-if="visibleTimeline&&!visibleTimeline.history_available" class="text-sm">Riwayat sebelum audit trail tidak tersedia.</p><Timeline v-else :items="timelineItems"/></section><Button v-if="canVoid(authStore.user?.role)&&activeTransaction.status === 'approved'" variant="destructive" size="sm" class="h-8" :disabled="pendingIds.has(activeTransaction.id)" :data-transaction-audit-trigger="`void-${activeTransaction.id}`" @click="requestVoid(activeTransaction.id)"><Ban/> Batalkan transaksi</Button></CardContent></ScrollArea>
        </Card>
      </div>

      <Sheet :open="detailOpen" @update:open="detailOpen=$event"><SheetContent side="right" class="!w-full overflow-y-auto sm:max-w-xl xl:hidden [&_[data-slot=sheet-close]]:!size-11"><SheetHeader class="pr-12"><SheetTitle>{{ activeTransaction?.keperluan }}</SheetTitle><SheetDescription>Detail transaksi dan jejak keputusan.</SheetDescription></SheetHeader><div v-if="activeTransaction" class="space-y-5 px-4 py-5"><section v-if="activeTransaction.keterangan"><h3 class="font-semibold">Keterangan</h3><p class="mt-1 text-sm leading-6 text-muted-foreground">{{ activeTransaction.keterangan }}</p></section><p class="text-3xl font-semibold tabular-nums">{{ activeTransaction.tipe==='pemasukan'?'+':'−' }} {{ formatRupiah(activeTransaction.jumlah) }}</p><StatusIndicator :tone="activeTransaction.status==='void'?'destructive':'success'">{{ activeTransaction.status==='void'?'Dibatalkan':'Disetujui' }}</StatusIndicator><p v-if="timelineLoading||timelineTransactionId!==activeTransaction.id" role="status">Memuat riwayat…</p><p v-else-if="timelineError" role="alert" class="text-sm text-destructive">{{ timelineError }} <Button variant="link" class="h-8 px-1" @click="emit('retryTimeline',activeTransaction.id)">Coba lagi</Button></p><p v-else-if="visibleTimeline&&!visibleTimeline.history_available">Riwayat sebelum audit trail tidak tersedia.</p><Timeline v-else :items="timelineItems"/><Button v-if="canVoid(authStore.user?.role)&&activeTransaction.status==='approved'" variant="destructive" class="h-11 xl:h-8" :disabled="pendingIds.has(activeTransaction.id)" :data-transaction-audit-trigger="`void-${activeTransaction.id}`" @click="requestVoid(activeTransaction.id)"><Ban/> Batalkan transaksi</Button></div></SheetContent></Sheet>

    </template>
  </div>
</template>
